UPDATE GITHUB_APP_TOKENS 
SET 
    app_token = #{app_token},
    expired_at = #{expired_at}
WHERE github_app_token_id = #{github_app_token_id}

UPDATE REPO_BRANCHES 
SET 
    base_sha = #{baseSha}
WHERE repo_branch_id = #{repoBranchId}

mapper.select:
SELECT repo_branch_id as repoBranchId, project_repo_id as projectRepoId, branch_name as branchName, created_at as createdAt, base_sha as baseSha FROM REPO_BRANCHES WHERE 1=1
AND project_repo_id = #{project_repo_id}
ORDER BY created_at DESC

SELECT COUNT(*)
FROM REPO_BRANCHES 
WHERE project_repo_id = #{project_repo_id}
AND branch_name = #{branch_name}

SELECT COUNT(DISTINCT rb.repo_branch_id) as total_branches, COUNT(DISTINCT pr.project_repo_id) as connected_repositories, COUNT(DISTINCT gw.github_webhook_id) as active_webhooks, COUNT(DISTINCT gat.github_app_token_id) as app_tokens, COUNT(DISTINCT pl.project_log_id) as github_activities FROM PROJECT p LEFT JOIN PROJECT_REPO pr ON p.project_id = pr.project_id LEFT JOIN REPO_BRANCHES rb ON pr.project_repo_id = rb.project_repo_id LEFT JOIN GITHUB_WEBHOOK gw ON pr.project_repo_id = gw.project_repo_id LEFT JOIN GITHUB_APP_TOKEN gat ON pr.project_repo_id = gat.project_repo_id LEFT JOIN PROJECT_USER pu ON p.project_id = pu.project_id LEFT JOIN PROJECT_LOG pl ON pu.project_user_id = pl.project_user_id AND pl.log_type LIKE 'GITHUB_%' WHERE p.project_id = #{project_id}
AND (pl.project_log_id IS NULL OR DATE(rb.created_at) >= #{date_from})
AND (pl.project_log_id IS NULL OR DATE(rb.created_at) <= #{date_to})

SELECT COUNT(DISTINCT pl.project_log_id) as total_activities, COUNT(DISTINCT CASE WHEN pl.log_description LIKE '%created%' THEN pl.project_log_id END) as branches_created, COUNT(DISTINCT CASE WHEN pl.log_description LIKE '%deleted%' THEN pl.project_log_id END) as branches_deleted, COUNT(DISTINCT CASE WHEN pl.log_description LIKE '%push%' THEN pl.project_log_id END) as pushes_made FROM PROJECT_LOG pl INNER JOIN PROJECT_USER pu ON pl.project_user_id = pu.project_user_id WHERE pu.user_id = #{user_id} AND pl.log_type LIKE 'GITHUB_%'
AND DATE(pl.project_log_id) >= #{date_from}
AND DATE(pl.project_log_id) <= #{date_to}
